    def __init__(self):
        self.levels = {}
        self.parked_vehicles = {}

    def add_level(self, level_id: str, spots: int) -> None:
        if not level_id or not isinstance(level_id, str):
            raise ValueError("Invalid level id")
        if not isinstance(spots, int) or spots <= 0:
            raise ValueError("Invalid spot count")
        if level_id in self.levels:
            raise GarageError("Level already exists")
        self.levels[level_id] = {'spots': spots, 'vehicles': []}

    def enter(self, plate: str, minute: int) -> str:
        if not plate or not isinstance(plate, str):
            raise ValueError("Invalid plate")
        if not isinstance(minute, int) or minute < 0:
            raise ValueError("Invalid minute")
        if plate in self.parked_vehicles:
            raise GarageError("Vehicle already parked")
        for level_id, level in self.levels.items():
            if level['spots'] > len(level['vehicles']):
                level['vehicles'].append(plate)
                self.parked_vehicles[plate] = {'level': level_id, 'minute': minute}
                return level_id
        raise GarageFull("Garage is full")

    def leave(self, plate: str, minute: int) -> int:
        if plate not in self.parked_vehicles:
            raise KeyError("Vehicle not parked")
        if not isinstance(minute, int) or minute < self.parked_vehicles[plate]['minute']:
            raise ValueError("Invalid minute")
        level_id = self.parked_vehicles[plate]['level']
        entry_minute = self.parked_vehicles[plate]['minute']
        self.levels[level_id]['vehicles'].remove(plate)
        del self.parked_vehicles[plate]
        return minute - entry_minute

    def get_level(self, plate: str) -> str:
        if plate not in self.parked_vehicles:
            raise KeyError("Vehicle not parked")
        return self.parked_vehicles[plate]['level']

    def get_free_spots(self, level_id: str) -> int:
        if level_id not in self.levels:
            raise KeyError("Level not found")
        return self.levels[level_id]['spots'] - len(self.levels[level_id]['vehicles'])

    def get_vehicles(self, level_id: str) -> list[str]:
        if level_id not in self.levels:
            raise KeyError("Level not found")
        return self.levels[level_id]['vehicles']

    def get_levels(self) -> list[str]:
        return list(self.levels.keys())
