"""roster.py

Manage a basketball team's roster under a salary cap.
"""

from typing import Any, Dict, List, Optional

POSITIONS = ("PG", "SG", "SF", "PF", "C")

class RosterError(Exception):
    """Base exception for roster errors."""
    pass

class CapExceeded(RosterError):
    """Exception raised when adding a player would exceed the salary cap."""
    pass

class Roster:
    def __init__(self, salary_cap: int):
        if not isinstance(salary_cap, int) or salary_cap <= 0:
            raise ValueError("Salary cap must be a positive integer")
        self.salary_cap = salary_cap
        self.players: Dict[str, Dict[str, Any]] = {}

    def add_player(self, name: str, position: str, salary: int) -> None:
        if not name:
            raise ValueError("Player name cannot be empty")
        if position not in POSITIONS:
            raise ValueError(f"Invalid position: {position}")
        if not isinstance(salary, int) or salary <= 0:
            raise ValueError("Salary must be a positive integer")
        if name in self.players:
            raise RosterError(f"Player {name} already on the roster")
        if self.get_payroll() + salary > self.salary_cap:
            raise CapExceeded("Adding this player would exceed the salary cap")
        self.players[name] = {"name": name, "position": position, "salary": salary}

    def remove_player(self, name: str) -> None:
        if name not in self.players:
            raise KeyError(f"Player {name} not found on the roster")
        del self.players[name]

    def get_players(self, position: Optional[str] = None) -> List[str]:
        if position is not None and position not in POSITIONS:
            raise ValueError(f"Invalid position: {position}")
        return [player for player, details in self.players.items() if position is None or details["position"] == position]

    def get_player(self, name: str) -> Dict[str, Any]:
        if name not in self.players:
            raise KeyError(f"Player {name} not found on the roster")
        return self.players[name]

    def get_payroll(self) -> int:
        return sum(player["salary"] for player in self.players.values())

    def get_cap_space(self) -> int:
        return self.salary_cap - self.get_payroll()
